'use strict';
const groups = [{"id": "centro", "number": "01", "title": "Centro & Santo Domingo", "timing": "LITTLE OUTINGS THROUGHOUT THE TRIP", "color": "pink", "description": "Start close to home. A walk, a church and a long lunch are enough for any one day.", "sections": [["WANDER A LITTLE", [["alcala", "Andador Macedonio Alcalá", "pedestrian street from Santo Domingo to the Zócalo"], ["zocalo", "Zócalo & the Cathedral", "shady main square for people-watching"], ["santodomingo", "Templo de Santo Domingo", "baroque church with a gilded, carved interior"], ["culturas", "Museo de las Culturas de Oaxaca", "regional history in the former convent next door"], ["jardin", "Jardín Etnobotánico", "garden of native plants and cacti", "Guided tours only: check the times."]]], ["EAT & LINGER", [["brujula", "Café Brújula", "local roaster for a coffee after work"], ["tlayuda", "A tlayuda", "giant crisp tortilla from a street grill"], ["mayordomo", "Hot chocolate at Mayordomo", "stone-ground chocolate, with pan de yema"], ["mole", "Mole negro at Las Quince Letras", "the dark, chocolatey one Oaxaca is famous for", "From our saved list. Go for a long lunch."]]]], "note": "One main thing and a meal can be plenty."}, {"id": "muertos", "number": "02", "title": "Día de Muertos", "timing": "THE BIG NIGHTS", "color": "blue", "description": "Altars, brass bands and candlelit cemeteries. Evenings only on work days; Sunday is free all day. ★★ don’t miss · ★ great if we can. Where there are options, pick one.", "sections": [["FRIDAY · PARADE NIGHT", [["comparsas", "Divertimuertos comparsa", "costumed parade with music, from El Llano to the Alameda de León", "6:30pm at El Llano, about 15 min walk north of the Zócalo."], ["verbena", "Verbena Xandú", "free street party with music and food stalls in the Zócalo", "7:30pm, right where the parade ends."]]], ["SATURDAY · THE CEMETERY NIGHT", [["altars", "Palacio de Gobierno tapete & Zócalo altars", "giant sand carpet and the altar exhibition", "Afternoon option: tapete open until 7pm, altars from 4pm. On the Zócalo, steps from the parade."], ["atzompa", "Santa María Atzompa", "pottery village holding an artisan fair outside its cemetery", "Afternoon option: about 8 km northwest, 25 min by taxi. Back in the Centro by 5pm."], ["xoxotapetes", "Xoxocotlán tapetes", "sand carpets and art displays in the town’s streets", "Afternoon option: go early, see them in daylight and stay for the vigil (this means skipping the parade). About 8 km south."], ["grancomparsa", "★ Gran Comparsa", "the city’s main parade: barrio groups, brass bands, diablos and catrinas", "6pm. Get a spot on Juárez or Morelos by 5:30pm, 5–10 min walk."], ["xoxo", "★★ Xoxocotlán cemetery vigil", "families keep watch by candlelight at flower-covered graves", "From 6pm, bands until 2am. About 8 km south, 30–60 min by taxi tonight: book the ride back."]]], ["SUNDAY · MARKETS & THE MUERTEADA", [["marketcrawl", "Centro market crawl", "breakfast at La Merced, pan de muerto at Benito Juárez, lunch at 20 de Noviembre", "Daytime option, all on foot. The easiest lead-in to Etla."], ["abastos", "Mercado de Abastos", "huge, chaotic market piled with marigolds, bread and altar supplies", "Daytime option, only if we like crowds. Keep bags in front."], ["xoxoaltares", "Xoxocotlán altar contest", "the town’s altar competition, then the children’s comparsa from 4pm", "Daytime option: 10am, about 8 km south. A long day if we also do Etla."], ["hechooaxaca", "Casa Hecho en Oaxaca", "artisan showcase at the Real Alhóndiga, plus the Palacio de Gobierno tapete", "Daytime option: a slow Centro day, all walkable. (Or the Tlacolula Sunday outing below, back by mid-afternoon.)"], ["etla", "★★ San Agustín Etla muerteada", "masked, satirical street theatre with brass bands, from house to house", "7pm, for a few hours, not all night. About 17 km north, 40–60 min: book a round-trip taxi that waits."], ["chinas", "Muerteada de Chinas Oaxaqueñas & Jalatlaco comparsa", "traditional dancers’ procession from El Llano, then a barrio comparsa", "Evening option instead of Etla, all walkable: 6pm, then about 8pm in Jalatlaco."]]], ["MONDAY · THE LAST NIGHT", [["tapetejalatlaco", "Jalatlaco sand tapestry", "sand carpet in the colourful old barrio", "After work, about 10 min walk northeast of the Zócalo."], ["xoxocomparsas", "★ Xoxocotlán comparsas", "local costumed processions with bands, going all night", "La Original from 5pm, Chicos Rebeldes from 6pm. About 8 km south: book the ride back."], ["panteon", "Concert at the Panteón San Miguel", "string ensemble, then Night of the Living Dead with a live score", "Evening option in the city: 6pm and 7pm."]]]], "note": "Taxis to book ahead: a driver who waits for Etla on Sunday (the one that matters most), and rides back from Xoxocotlán on Saturday and Monday night. Agree the price first: Oaxaca taxis don’t use meters. Times can still change, so check the state tourism page before heading out.", "link": ["Official updates", "https://www.facebook.com/SECTUR.GobOax/"]}, {"id": "markets", "number": "03", "title": "Markets & Jalatlaco", "timing": "SEPARATE AFTERNOONS & EVENINGS", "color": "green", "description": "Smoke, chocolate and cobbled lanes. Come hungry.", "sections": [["ONE AFTERNOON", [["veinte", "Mercado 20 de Noviembre", "the Pasillo de Humo: pick your meat and they grill it"], ["juarezmkt", "Mercado Benito Juárez", "chocolate, cheese, mezcal and chapulines"]]], ["ANOTHER AFTERNOON", [["jalatlaco", "Barrio de Jalatlaco", "cobbled lanes, murals and small cafés"]]], ["A SEPARATE EVENING", [["mezcaloteca", "Mezcaloteca", "guided tasting of small-batch mezcals", "Book ahead."]]], ["ANOTHER SUNSET", [["fortin", "Cerro del Fortín", "hill above the city for sunset"]]]], "note": "Markets for lunch after work; Jalatlaco, Mezcaloteca and Fortín on separate outings. No need to fit them into one afternoon."}, {"id": "cooking", "number": "04", "title": "A cooking class", "timing": "A MORNING OFF WORK", "color": "yellow", "description": "Shop the market with a cook, then make it all from scratch.", "sections": [["MARKET TO TABLE", [["class", "Market visit & cooking class", "salsas, tortillas and a mole", "Book ahead."]]]], "note": "Book on a day off, or confirm an afternoon class instead. Your cooking becomes the meal: check the start time and duration."}, {"id": "food", "number": "05", "title": "Food & drinks", "timing": "FROM OUR SAVED LIST", "color": "green", "description": "A shortlist to choose from, with no need to try them all. Pair a meal with the nearest walk.", "sections": [["BREAKFAST & BREAD", [["boulenc", "Boulenc", "bakery and brunch in Jalatlaco"], ["bodaega", "Bodæga", "small artisan bakery on Hidalgo"]]], ["LONG LUNCHES, LATE SUPPERS", [["levadura", "Levadura de Olla", "Thalía Barrios’s home-style Oaxacan cooking", "Book ahead."], ["humo", "La Cocina de Humo", "her tasting menu cooked over a wood fire", "Book well ahead."], ["danzantes", "Los Danzantes", "contemporary Oaxacan food in an open courtyard"], ["tierrasol", "Tierra del Sol", "Mixtec cooking on a rooftop"], ["copal", "Copal", "restaurant on Alcalá, above Santo Domingo"]]], ["A DRINK IN THE EVENING", [["selva", "Selva", "cocktails made with Oaxacan ingredients"]]]], "note": "Pair a dinner with whatever walk is nearby."}, {"id": "montealban", "number": "★", "title": "Monte Albán", "timing": "SUGGESTED CHOICE · HALF A DAY", "color": "yellow", "description": "A Zapotec city on a flattened hilltop above the valley.", "sections": [["AFTER WORK OR ON A DAY OFF", [["alban", "Monte Albán", "ruins, plazas and wide valley views", "Morning on a day off, or early afternoon after work. Very little shade: bring a hat and water."], ["arrazola", "San Antonio Arrazola", "nearby village of painted wooden alebrijes", "Optional: only if you have the energy."]]]], "note": "Choose this trip OR Hierve el Agua. Listed hours: 8am–5pm, last entry 4pm; allow time for transport and exploring. Arrazola is optional.", "weekend": true, "link": ["Official visiting hours", "https://lugares.inah.gob.mx/es/node/5803"]}, {"id": "hierve", "number": "★", "title": "Hierve el Agua", "timing": "ALTERNATIVE · A DAY OFF", "color": "blue", "description": "Petrified waterfalls and mineral pools, with a tour or driver. Choose this instead of Monte Albán.", "sections": [["THE TRIP, WITH AT MOST ONE EXTRA STOP", [["tule", "Árbol del Tule", "one of the widest trees in the world", "Optional: choose at most one extra stop."], ["mitla", "Mitla", "ruins covered in stone fretwork", "Optional: choose at most one extra stop."], ["palenque", "A mezcal palenque", "family distillery around Santiago Matatlán", "Optional: choose at most one extra stop."], ["hierve", "Hierve el Agua", "petrified waterfalls and clifftop mineral pools", "It sometimes closes without warning: check the week before."]]]], "note": "Reserve a non-working day and keep the next afternoon free. Choose at most one of Tule, Mitla or a palenque; confirm Hierve is open.", "weekend": true}, {"id": "tlacolula", "number": "+", "title": "Tlacolula & Teotitlán", "timing": "A SUNDAY OUTING", "color": "pink", "description": "The market and lunch are enough. The weaving village is an optional extra if you feel like it.", "sections": [["ON A SUNDAY", [["tlacolula", "Tlacolula market", "one of the biggest weekly markets in the valley", "Sundays only."], ["barbacoa", "Barbacoa for lunch", "slow-cooked goat or lamb at the market"], ["teotitlan", "Teotitlán del Valle", "rugs made on wooden looms", "Optional; head back to town after lunch if you prefer."]]]], "note": "Bring cash."}];
const optional = [["tilcajete", "San Martín Tilcajete", "another alebrije village, south of the city"], ["temazcal", "A temazcal", "traditional steam bath, for a rainy afternoon"], ["tejate", "Tejate", "cold maize and cacao drink from the markets"], ["chapulines", "Chapulines", "toasted grasshoppers with lime and chilli, if brave"]];
const KEY='frolicking-nicky-oaxaca-v2';
let checked={}; let storageOK=true;
try { const saved=JSON.parse(localStorage.getItem(KEY)||'{}'); if(saved && typeof saved==='object' && !Array.isArray(saved)) checked=saved; } catch {storageOK=false;}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const OPTIONAL_IDS=new Set(['arrazola','tule','mitla','palenque','teotitlan','altars','atzompa','xoxotapetes','marketcrawl','abastos','xoxoaltares','hechooaxaca','chinas','panteon']);
let chosenTrip='montealban';
try {if(localStorage.getItem(KEY+'-trip')==='hierve')chosenTrip='hierve';}catch{}
const tripChoice=document.querySelector('#trip-choice');
tripChoice.value=chosenTrip;
const countedIds=()=>groups.filter(g=>!['montealban','hierve'].includes(g.id)||g.id===chosenTrip).flatMap(g=>g.sections.flatMap(s=>s[1].map(r=>r[0]))).filter(id=>!OPTIONAL_IDS.has(id));
function item(row,extra=false) {const [id,title,desc,note]=row;return `<label class="task${checked[id]===true?' completed':''}"><input type="checkbox" id="${esc(id)}" data-extra="${extra}" ${checked[id]===true?'checked':''}><span class="checkmark" aria-hidden="true"></span><span class="task-copy"><span class="task-title">${esc(title)}</span> <span class="specialty">(${esc(desc)})</span>${note?`<span class="task-note">${esc(note)}</span>`:''}</span></label>`;}
const PHOTOS={"centro": [[["/assets/oax-alcala.jpeg", "Colourful colonial houses along the Andador Macedonio Alcalá", 1400, 1400, "Zitenshi", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Macedonio_de_Alcal%C3%A1.jpg"], ["/assets/oax-jardin.jpeg", "Tall organ-pipe cacti in the Jardín Etnobotánico beside the old convent", 1400, 1050, "Kaldari", "CC0", "https://commons.wikimedia.org/wiki/File:Jard%C3%ADn_Etnobot%C3%A1nico_de_Oaxaca_06.JPG"]], [["/assets/oax-tlayuda.jpeg", "A tlayuda topped with meat, avocado and grilled spring onions", 1400, 1050, "Gomez.erick", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:TLAYUDA.jpg"], ["/assets/oax-chocolate.jpeg", "Cacao being ground in the molinos at a Mayordomo chocolate shop", 930, 1400, "LBM1948", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Oaxaca_de_Ju%C3%A1rez,_23.jpg"]]], "muertos": [[["/assets/oax-comparsa.jpeg", "Costumed dancers with bells on their legs in a Día de Muertos comparsa", 933, 1400, "David Cabrera", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Cascabeles.jpg"]], [["/assets/oax-xoxo.jpeg", "Families keeping vigil among candlelit graves at the Xoxocotlán cemetery", 1400, 933, "Pedro Daniel Godínez Corona", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Velando_en_el_Pante%C3%B3n_de_Xoxocotl%C3%A1n.jpg"]], [["/assets/oax-altar.jpeg", "A Día de Muertos altar heaped with marigolds, candles, fruit and photos", 1400, 1050, "Jmillan325", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Altar_de_D%C3%ADa_de_Muertos_en_el_Tule_Oaxaca.jpg"]], []], "markets": [[["/assets/oax-mercado.jpeg", "Grill smoke drifting through the meat aisle of Mercado 20 de Noviembre", 1400, 937, "ProtoplasmaKid", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Mercado_20_de_noviembre_-_Oaxaca_de_Ju%C3%A1rez_-_10.jpg"]], []], "cooking": [[["/assets/oax-mole.jpeg", "A plate of mole negro with rice", 1400, 1050, "ProtoplasmaKid", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Mole_negro_de_Oaxaca_con_arroz.jpg"]]], "montealban": [[["/assets/oax-montealban.jpeg", "The Gran Plaza of Monte Albán on its flattened hilltop above the valley", 1400, 1060, "Infrogmation", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Monte_Alb%C3%A1n_Oaxaca_1976_01.jpg"]]], "hierve": [[["/assets/oax-hierve.jpeg", "The white, petrified waterfall of Hierve el Agua spilling down a green mountainside", 1400, 1050, "Adrián Cerón", "CC BY-SA 3.0", "https://commons.wikimedia.org/wiki/File:Hierve_el_agua.JPG"], ["/assets/oax-mitla.jpeg", "Stone fretwork walls around a courtyard at Mitla", 1400, 933, "DavidConFran", "CC BY-SA 3.0", "https://commons.wikimedia.org/wiki/File:Patio_Grupo_Norte.JPG"]]], "tlacolula": [[["/assets/oax-tlacolula.jpeg", "Stalls of fruit, flowers and bread at the Tlacolula Sunday market", 1400, 933, "Bluerasberry", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Tlacolula_Market_230122_62.jpg"], ["/assets/oax-teotitlan.jpeg", "A weaver at a wooden loom in Teotitlán del Valle, with finished rugs behind", 1280, 854, "Axel Alvarado Chávez", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Tejido_de_Tapetes_Artesanales_en_Telar._Teotitl%C3%A1n_Del_Valle,_Oaxaca.jpg"]]], "food": [[], [["/assets/oax-fire.jpeg", "A woman stirring a big pot of mole over a wood fire", 1050, 1400, "Diego Emiliano Jaramillo Navarro", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Do%C3%B1a_Mari,_la_Reina_del_Mole.jpg"], ["/assets/oax-tlayuda-grill.jpeg", "A tlayuda vendor at a street grill in Oaxaca at night", 787, 1400, "Alex Haulman", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Tlayuda_vendor_in_Oaxaca_City.jpg"]], []]};
const fig=([src,alt,w,h,by,lic,url])=>`<figure class="fn-v-photo"><a href="${src}" target="_blank" rel="noopener"><img src="${src}" alt="${esc(alt)}" width="${w}" height="${h}" loading="lazy"></a>${by?`<figcaption>Photo: ${by} · <a href="${url}" target="_blank" rel="noopener noreferrer">${lic}</a></figcaption>`:''}</figure>`;
let rowN=0;
document.querySelector('#itinerary').innerHTML=groups.map(g=>`<section id="${g.id}" class="outing fn-split ${g.color} ${g.weekend?'weekend':''}" aria-labelledby="title-${g.id}"><div class="outing-heading"><span class="number" aria-hidden="true">${g.number}</span><div><p class="eyebrow">${g.timing}</p><h2 id="title-${g.id}">${g.title}</h2><p class="section-desc">${g.description}</p></div><span class="group-count" id="count-${g.id}" aria-label="Section completion"></span></div><div class="outing-body fn-split-body">${g.sections.map(([title,rows],si)=>{const ps=(PHOTOS[g.id]||[])[si]||[];const card=`<div class="task-group"><h3>${title}</h3>${rows.map(r=>item(r,OPTIONAL_IDS.has(r[0]))).join('')}</div>`;return ps.length?`<div class="fn-v-row${rowN++%2?' fn-v-rev':''}"><div class="fn-v-side">${ps.map(fig).join('')}</div>${card}</div>`:card;}).join('')}</div><div class="outing-note"><p>${g.note}</p>${g.link?`<a href="${g.link[1]}" target="_blank" rel="noopener noreferrer">${g.link[0]} ↗︎</a>`:''}</div></section>`).join('');
document.querySelector('#optional-list').innerHTML=optional.map(r=>item(r,true)).join('');
function update(announce=false){const mainIds=countedIds();const done=mainIds.filter(id=>checked[id]===true).length;const percent=Math.round(done/mainIds.length*100);document.querySelector('#progress-count').textContent=done;document.querySelector('#progress-total').textContent=`of ${mainIds.length} places & moments`;document.querySelector('#percent').textContent=percent+'%';document.querySelector('#progress').value=percent;document.querySelector('#progress').textContent=percent+'%';groups.forEach(g=>{const inactive=['montealban','hierve'].includes(g.id)&&g.id!==chosenTrip;const ids=g.sections.flatMap(s=>s[1].map(r=>r[0])).filter(id=>!OPTIONAL_IDS.has(id));document.querySelector('#count-'+g.id).textContent=inactive?"Alternative: excluded from checklist":`${ids.filter(id=>checked[id]===true).length} / ${ids.length}`;});const extra=[...optional.map(r=>r[0]),...OPTIONAL_IDS].filter(id=>checked[id]===true).length;document.querySelector('#extra-count').textContent=`${extra} optional ${extra===1?'stop':'stops'} done`;document.querySelector('#save-note').textContent=storageOK?'Progress saved on this device.':'Progress works here, but saving is unavailable in this browser.';if(announce)document.querySelector('#announcement').textContent=`${done} of ${mainIds.length} main items complete. ${extra} optional stops done.`;}
tripChoice.addEventListener('change',()=>{chosenTrip=tripChoice.value;try{localStorage.setItem(KEY+'-trip',chosenTrip);}catch{}update(true);});
function persist(){try{localStorage.setItem(KEY,JSON.stringify(checked));storageOK=true;}catch{storageOK=false;}}
document.addEventListener('change',e=>{if(!e.target.matches('.task input'))return;checked[e.target.id]=e.target.checked;e.target.closest('.task').classList.toggle('completed',e.target.checked);persist();update(true);});
window.addEventListener('storage',e=>{if(e.key===KEY+'-trip'){chosenTrip=e.newValue==='hierve'?'hierve':'montealban';tripChoice.value=chosenTrip;update();return;}if(e.key!==KEY)return;try{const next=JSON.parse(e.newValue||'{}');checked=next&&typeof next==='object'&&!Array.isArray(next)?next:{};}catch{checked={};}document.querySelectorAll('.task input').forEach(el=>{el.checked=checked[el.id]===true;el.closest('.task').classList.toggle('completed',el.checked);});update();});
const dialog=document.querySelector('#reset-dialog');document.querySelector('#reset').addEventListener('click',()=>dialog.showModal());document.querySelector('#cancel-reset').addEventListener('click',()=>dialog.close());document.querySelector('#confirm-reset').addEventListener('click',()=>{checked={};persist();document.querySelectorAll('.task input').forEach(el=>{el.checked=false;el.closest('.task').classList.remove('completed');});update(true);dialog.close();});
update();
